-- Ledger 901 (plan SPEC §1.2, §2.1-2.2): `meal_items`, what is ON a meal's
-- plate, one row per rating target (a fresh food, a fresh recipe, or each
-- food or recipe of a served container, grouped by `storage_item_id`).
-- `meal_foods` stays the exposure table and `meal_recipes` the recipe list;
-- both are derived from these rows by new writes, and nothing reads them
-- differently.
--
-- Wholly additive: one new table. No existing row is updated or deleted.
-- Generated by drizzle-kit, then the backfill appended by hand (the 0020
-- pattern); drizzle's migrator runs this file in one transaction. The
-- backfill gives every existing meal its items exactly (passes R, F, C), so
-- `meal_foods`, `meal_recipes`, `meal_storage_items`, the links and every
-- rating stay byte-identical; every backfilled row is `inferred` (chair
-- decision §10.1: no "Left out" line on them). The boot heal
-- `healMealItems` (db/migrate.ts) re-runs the same statement for any meal an
-- older writer leaves without exact items.
CREATE TABLE "meal_items" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"meal_id" uuid NOT NULL,
	"position" integer NOT NULL,
	"food_id" uuid,
	"recipe_id" uuid,
	"storage_item_id" uuid,
	"counted_food_ids" uuid[] DEFAULT '{}'::uuid[] NOT NULL,
	"rating" smallint,
	"inferred" boolean DEFAULT false NOT NULL,
	CONSTRAINT "meal_items_one_ref" CHECK (num_nonnulls("meal_items"."food_id", "meal_items"."recipe_id") = 1),
	CONSTRAINT "meal_items_counted_recipe_only" CHECK ("meal_items"."recipe_id" IS NOT NULL OR cardinality("meal_items"."counted_food_ids") = 0),
	CONSTRAINT "meal_items_rating_range" CHECK ("meal_items"."rating" BETWEEN 1 AND 5)
);
