CREATE INDEX "meal_items_recipe_id_idx" ON "meal_items" USING btree ("recipe_id");--> statement-breakpoint
CREATE INDEX "meal_items_storage_item_id_idx" ON "meal_items" USING btree ("storage_item_id");
